CREATE TABLE CORE_DIM.T_FACT_WAWI_ITEM_VARIANT_SALES_PRICE (
   int_org_sid                         NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier (surrogate key) for the internal organization.',
   int_org_type_cd                     VARCHAR(20)     NOT NULL COMMENT 'The code identifying the discriminators for internal organizations.',
   country_org_sid                     NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier (surrogate key) for the country organization.',
   country_org_cd                      VARCHAR(2)      NOT NULL COMMENT 'The code of the business country for which the related country organization is responsible. (The business country is not identical to a political country.)',
   wawi_item_variant_sid               NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier (surrogate key) of the Wawi item variant.',
   wawi_item_sid                       NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier (surrogate key) of the Wawi item.',
   dwh_valid_from_tmsp                 TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
   dwh_valid_to_tmsp                   TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
   dwh_valid_fg                        BOOLEAN         NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
   sales_net_price                     NUMBER(38, 5)   NOT NULL COMMENT 'The net price (i.e. excluding VAT) for which products that are related to the Wawi item variant are sold in the given store or warehouse.',
   sales_gross_price                   NUMBER(38, 5)   NOT NULL COMMENT 'The gross price (i.e. including VAT) for which products that are related to the Wawi item variant are sold in the given store or warehouse.',
   deposit_val                         NUMBER(38, 5)   COMMENT 'The deposit amount for this Wawi item variant. E.g. 25c for a plastic bottle. (This attribute is only filled, if there is a deposit.)',
   tax_pct                             NUMBER(38, 5)   NOT NULL COMMENT 'The actual tax percentage which is applicable for the Wawi item variant in the given store or warehouse. (In case several taxes apply, this is the total tax percentage.)',
   curr_cd                             VARCHAR(3)      NOT NULL COMMENT 'The code identifying the currency according to ISO-4217.',
   dwh_created_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   dwh_updated_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
   dwh_load_id                         NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
   dwh_node_cd                         VARCHAR(20)     NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
   CONSTRAINT PK_T_FACT_WAWI_ITEM_VARIANT_SALES_PRICE PRIMARY KEY (int_org_sid, wawi_item_variant_sid, dwh_valid_from_tmsp) NOT ENFORCED
 )  COMMENT= 'A derived table tracking the sales prices of Wawi item variants in stores and warehouses. (For reasons of data volume this table does not contain one record per day, but is historized.)';
